def modp(n: int, p: int):
    if n == 0:
        return 1

    result = 1
    base = 2
    n = n % (p - 1)  # Optimization for large n

    while n > 0:
        if n % 2 == 1:
            result = (result * base) % p
        base = (base * base) % p
        n //= 2

    return result
